<template><main class="league-view"><header><p>{{ t('competitions.league.swarmEyebrow') }}</p><h1>{{ t('competitions.league.swarmTitle') }}</h1><span>{{ t('competitions.league.swarmDescription') }}</span></header><section v-if="loading">{{ t('competitions.league.loading') }}</section><section v-else class="card"><h2>{{ t('competitions.league.graphTitle') }}</h2><p>{{ graph.mode }} · {{ graph.graphId }}</p><div class="nodes"><span v-for="node in graph.nodes" :key="node.id" :class="node.type">{{ node.label }}</span></div><p>{{ t('competitions.league.graphDetail', { nodes: graph.nodes.length, links: graph.links.length }) }}</p></section></main></template>
<script setup>import { onMounted, ref } from 'vue'; import { useI18n } from 'vue-i18n'; import { useRoute } from 'vue-router'; import { api } from '../lib/api'; import { leagueApiBase } from '../competition/leagueApi.js'; const { t }=useI18n(); const route=useRoute(); const loading=ref(true); const graph=ref({nodes:[],links:[],mode:'edition',graphId:'—'}); onMounted(async()=>{try{graph.value=(await api.get(`${leagueApiBase(route.params.competitionEditionSlug)}/graph`)).data}finally{loading.value=false}})</script>
<style scoped>.league-view{display:grid;gap:var(--space-6)}header,.card{display:grid;gap:var(--space-3);background:var(--color-surface);border:var(--border-width-thin) solid var(--color-border);padding:var(--space-5)}h1,h2{font-family:var(--font-family-display);margin:0}header p,.card p,header span{color:var(--color-text-muted);margin:0}.nodes{display:flex;flex-wrap:wrap;gap:var(--space-2)}.nodes span{border:var(--border-width-thin) solid var(--color-border);padding:var(--space-2);font-size:var(--font-size-xs)}.competition{background:var(--color-accent);color:var(--color-accent-contrast)}.result{background:var(--color-surface-inset)}</style>
